// Read what the person typed and check it BEFORE anything touches the database.
// Anything malformed goes to a usage message instead of falling through.
const OWNER_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const msg = $input.first().json.message || {};
const chat_id = String((msg.chat && msg.chat.id) || '');
if (!chat_id) return [];
const text = String(msg.text || '').trim();
const first_name = (msg.from && msg.from.first_name) || '';
let command = '';
let args = [];
if (text.startsWith('/')) {
  const parts = text.split(/\s+/);
  command = parts[0].slice(1).split('@')[0].toLowerCase();
  args = parts.slice(1).join(' ').split(/[\s,;]+/).filter(Boolean);
}
const aliases = { start: 'start', help: 'start', watch: 'watch', follow: 'watch', add: 'watch',
  unwatch: 'unwatch', unfollow: 'unwatch', remove: 'unwatch', list: 'list', report: 'report',
  stop: 'stop', status: 'status', simulate: 'simulate' };
let route = aliases[command] || 'unknown';
const is_owner = chat_id === OWNER_CHAT_ID;
if (route === 'simulate' && !is_owner) route = 'unknown';

// /watch also takes company names: commas separate names ("tesla, turkish airlines"),
// otherwise spaces do ("TSLA MSFT"). Each term keeps the text as typed; at most 30 per message.
const MAX_TERMS = 30;
let terms = [];
let terms_dropped = 0;
if (route === 'watch') {
  const rest = text.replace(/^\S+/, '').trim();
  const pieces = /[,;]/.test(rest) ? rest.split(/[,;]/) : rest.split(/\s+/);
  const seenTerms = new Set();
  for (const piece of pieces) {
    const term = piece.replace(/\s+/g, ' ').trim().replace(/^\$/, '').slice(0, 60);
    if (!term || seenTerms.has(term.toLowerCase())) continue;
    seenTerms.add(term.toLowerCase());
    terms.push(term);
  }
  terms_dropped = Math.max(0, terms.length - MAX_TERMS);
  terms = terms.slice(0, MAX_TERMS);
}

const SYMBOL = /^[A-Z0-9^][A-Z0-9.=^-]{0,11}$/;
const upper = args.map(a => a.toUpperCase().replace(/^\$/, ''));
const symbols = Array.from(new Set(upper.filter(s => SYMBOL.test(s))));
const malformed = upper.filter(s => !SYMBOL.test(s));
let usage_text = '';
if (route === 'watch' && !terms.length) {
  usage_text = 'Usage: /watch tesla, airbus, turkish airlines\nor with Yahoo Finance tickers: /watch AAPL MSFT MC.PA\nSeparate company names with commas.';
  route = 'usage';
}
if (route === 'unwatch' && !symbols.length) {
  usage_text = (malformed.length ? 'That does not look like a stock symbol: ' + malformed.join(', ') + '\n' : '') +
    'Usage: /' + route + ' AAPL MSFT\nUse Yahoo Finance symbols, e.g. AAPL, NVDA, MC.PA (Paris).';
  route = 'usage';
}
let sim_source = '';
let sim_down = false;
if (route === 'simulate') {
  const SOURCES = ['yahoo', 'alphavantage', 'fx', 'news', 'ai', 'reset'];
  sim_source = (args[0] || '').toLowerCase();
  const state = (args[1] || '').toLowerCase();
  if (!SOURCES.includes(sim_source) || (sim_source !== 'reset' && !['down', 'up'].includes(state))) {
    usage_text = 'Usage: /simulate <yahoo|alphavantage|fx|news|ai> <down|up>\nor /simulate reset';
    route = 'usage';
  }
  sim_down = state === 'down';
}
return [{ json: { route, chat_id, first_name, text, symbols, malformed, terms, terms_dropped, usage_text, sim_source, sim_down, is_owner } }];

// Before looking anything up: skip terms that are already a symbol on the list,
// and look nothing up at all if the person is already at the 30-stocks cap.
const p = $('Parse And Validate Command').first().json;
const CAP = 30;
const existing = $input.all().map(i => i.json).filter(r => r.symbol).map(r => String(r.symbol).toUpperCase());
const already = p.terms.filter(t => existing.includes(t.toUpperCase())).map(t => t.toUpperCase());
const toResolve = p.terms.filter(t => !existing.includes(t.toUpperCase()));
const room = Math.max(0, CAP - existing.length);
const overCap = room ? [] : toResolve;
const meta = { already, overCap, existing, existing_count: existing.length, cap: CAP, terms_dropped: p.terms_dropped || 0 };
if (!toResolve.length || !room) return [{ json: { none: true, meta } }];
return [{ json: { none: false, terms: toResolve, chat_id: p.chat_id, meta } }];

// Keep only what the lookup actually found, skip stocks already followed (or named twice in one message),
// and stop at the 30-stocks cap. Every term gets an outcome that the reply reports back.
const plan = $('Plan New Stocks').first().json;
const meta = plan.meta;
const resolved = $input.all().map(i => i.json).filter(r => r && r.term);
const answered = new Set(resolved.map(r => String(r.term).toLowerCase()));
const followed = new Set(meta.existing);
let room = meta.cap - meta.existing_count;
const result = { added: [], already: meta.already.map(t => ({ term: t })), overCap: [], notFound: [], unavailable: [],
  existing_count: meta.existing_count, cap: meta.cap, terms_dropped: meta.terms_dropped };
// If the lookup itself failed, the person is told to retry rather than told the stock does not exist.
for (const t of plan.terms) if (!answered.has(t.toLowerCase())) result.unavailable.push({ term: t });
for (const r of resolved) {
  if (r.status === 'lookup_unavailable') { result.unavailable.push({ term: r.term }); continue; }
  if (r.status !== 'found' || !r.symbol) { result.notFound.push({ term: r.term }); continue; }
  const symbol = String(r.symbol).toUpperCase();
  const entry = { term: r.term, symbol, name: r.name || '', method: r.method };
  if (followed.has(symbol)) {
    if (!result.added.some(a => a.symbol === symbol)) result.already.push(entry);
    continue;
  }
  if (room <= 0) { result.overCap.push(entry); continue; }
  followed.add(symbol);
  room--;
  result.added.push(entry);
}
if (!result.added.length) return [{ json: { none: true, result } }];
return result.added.map(a => ({ json: { none: false, chat_id: plan.chat_id, symbol: a.symbol, name: a.name, result } }));

// Tell the person what each thing they typed was understood as, so a wrong match is easy to spot.
const p = $('Parse And Validate Command').first().json;
const meta = $('Plan New Stocks').first().json.meta;
let r = null;
try { r = $('Pick Stocks To Save').first().json.result; } catch (e) { r = null; }
if (!r) r = { added: [], already: meta.already.map(t => ({ term: t })), overCap: meta.overCap.map(t => ({ term: t })),
  notFound: [], unavailable: [], existing_count: meta.existing_count, cap: meta.cap, terms_dropped: meta.terms_dropped };
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = e => (e.symbol && e.symbol.toUpperCase() !== String(e.term).toUpperCase())
  ? esc(e.term) + ' → <b>' + esc(e.symbol) + '</b>' : '<b>' + esc(e.symbol || e.term) + '</b>';
const lines = [];
for (const a of r.added) {
  lines.push('✅ ' + label(a) + (a.name ? ' (' + esc(a.name) + ')' : '') + (a.method === 'ai' ? ' <i>(matched by AI, double-check)</i>' : ''));
}
if (r.already.length) lines.push('ℹ️ Already on your list: ' + r.already.map(label).join(', '));
if (r.notFound.length) lines.push('❌ Not found on Yahoo Finance: ' + esc(r.notFound.map(e => e.term).join(', ')) + '. Check the spelling, or use the ticker (e.g. MC.PA for LVMH).');
if (r.unavailable.length) lines.push("🕓 Couldn't look this up right now, try again later or use the ticker: " + esc(r.unavailable.map(e => e.term).join(', ')));
if (r.overCap.length) lines.push('⛔ Limit of ' + r.cap + ' stocks reached. Not added: ' + r.overCap.map(label).join(', ') + '. Use /unwatch to make room.');
if (r.terms_dropped) lines.push('ℹ️ Only the first 30 names in a message are looked at; ' + r.terms_dropped + ' more were ignored.');
const total = r.existing_count + r.added.length;
lines.push('You follow ' + total + '/' + r.cap + ' stocks. /list to see them, /report for a report now.');
return [{ json: { chat_id: p.chat_id, text: lines.join('\n') } }];

const p = $('Parse And Validate Command').first().json;
const existing = $input.all().map(i => i.json).filter(r => r.symbol).map(r => String(r.symbol).toUpperCase());
const remove = p.symbols.filter(s => existing.includes(s));
const notFound = p.symbols.filter(s => !existing.includes(s));
const meta = { remove, notFound, remaining: existing.length - remove.length };
if (!remove.length) return [{ json: { none: true, meta } }];
return remove.map(s => ({ json: { none: false, chat_id: p.chat_id, symbol: s, meta } }));

const p = $('Parse And Validate Command').first().json;
const meta = $('Plan Removals').first().json.meta;
const lines = [];
if (meta.remove.length) lines.push('🗑 No longer following: ' + meta.remove.join(', '));
if (meta.notFound.length) lines.push('ℹ️ Not on your list: ' + meta.notFound.join(', '));
lines.push('You now follow ' + meta.remaining + ' stocks. /list to see them.');
return [{ json: { chat_id: p.chat_id, text: lines.join('\n') } }];

const p = $('Parse And Validate Command').first().json;
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map(i => i.json).filter(r => r.symbol).sort((a, b) => String(a.symbol).localeCompare(String(b.symbol)));
let text;
if (!rows.length) text = 'You do not follow any stocks yet. Try /watch AAPL MSFT';
else text = '⭐ <b>Your stocks</b> (' + rows.length + '/30)\n' + rows.map(r => '• <b>' + esc(r.symbol) + '</b>' + (r.name ? ' ' + esc(r.name) : '')).join('\n');
return [{ json: { chat_id: p.chat_id, text } }];

// Each on-demand report costs one AI call and some data-source quota, so we cap it per person per day.
const p = $('Parse And Validate Command').first().json;
const LIMIT = 5;
const used = $input.all().map(i => i.json).filter(r => r.chat_id).length;
return [{ json: { chat_id: p.chat_id, used, limit: LIMIT, allowed: used < LIMIT } }];

const p = $('Parse And Validate Command').first().json;
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const labels = { yahoo: 'Stock prices (Yahoo, primary)', alphavantage: 'Stock prices (Alpha Vantage, backup)', fx: 'Exchange rates', news: 'Headlines', ai: 'AI summary' };
const health = $('Read Source Health').all().map(i => i.json).filter(h => h.source);
const lines = ['🩺 <b>System status</b>'];
for (const key of Object.keys(labels)) {
  const h = health.find(x => x.source === key) || {};
  let state = '✅ working';
  if (h.simulate_down) state = '🧪 switched off for a demo';
  else if ((h.consecutive_failures || 0) >= 3) state = '🔌 skipped after ' + h.consecutive_failures + ' failures in a row (retried after 30 min)';
  else if ((h.consecutive_failures || 0) > 0) state = '⚠️ failed ' + h.consecutive_failures + ' time(s) in a row';
  else if (h.last_status === 'partial') state = '✅ working (some symbols missing)';
  lines.push(labels[key] + ': ' + state);
}
const last = $input.all().map(i => i.json).filter(r => r.report_date);
if (last.length) {
  const r = last[0];
  lines.push('');
  lines.push('Last report: ' + esc(r.report_date) + ' (' + esc(r.trigger) + '), ' + esc(r.status) + '. Sections with problems: ' + esc(r.sections_down || 'none') + '. Summary by: ' + esc(r.summary_by) + '.');
}
return [{ json: { chat_id: p.chat_id, text: lines.join('\n') } }];

// Owner-only demo switch: makes a data source fail on purpose, to show the system recovering live.
const p = $input.first().json;
const all = ['yahoo', 'alphavantage', 'fx', 'news', 'ai'];
const targets = p.sim_source === 'reset' ? all : [p.sim_source];
const down = p.sim_source === 'reset' ? false : p.sim_down;
return targets.map(s => ({ json: { source: s, simulate_down: down, consecutive_failures: 0, last_status: 'ok' } }));
